// Dated, local territorial layers. No interpolation of historical borders.
export function snapshotFor(snapshots,year){let found=null;for(const s of snapshots){if(s.year>year)break;found=s;}return found;}
export function normalizeGeometry(geometry,geoArea){const poly=r=>geoArea({type:'Polygon',coordinates:r})>2*Math.PI?r.map(a=>a.slice().reverse()):r;return {type:geometry.type,coordinates:geometry.type==='Polygon'?poly(geometry.coordinates):geometry.coordinates.map(poly)};}
const translations={'Celts':'Кельтские общества островов','Celtic kingdoms':'Кельтские королевства','Celtiberians':'Кельтиберы','Hallstatt culture':'Гальштатский ареал','La Tène culture':'Латенский ареал','Byzantine Empire':'Византийская империя','Kyivan Rus':'Киевская Русь','Kievan Rus':'Киевская Русь','Novgorod':'Новгород','Principality of Novgorod':'Новгородская земля','Egypt':'Египет','Roman Empire':'Римская империя','Roman Republic':'Римская республика','Rome':'Рим','Persian Empire':'Персидская держава','Ottoman Empire':'Османская империя','Mongol Empire':'Монгольская империя','Ming':'Мин','Han':'Хань','Indus valley civilization':'Индская цивилизация','Norte Chico':'Норте-Чико','Russia':'Россия','Ukraine':'Украина','Serbia':'Сербия','Bulgaria':'Болгария','Greece':'Греция','Georgia':'Грузия','Romania':'Румыния','France':'Франция','Spain':'Испания','China':'Китай','India':'Индия','United Kingdom':'Великобритания','Germany':'Германия','United States':'США','Japan':'Япония','Jōmon':'Дзёмон','Boii':'Бойи','Galatians':'Галаты','Galatia':'Галатия'};
export function areaName(f){return f.properties.title||translations[f.properties.name]||f.properties.name;}
export function areaColor(f){if(f.properties.color)return f.properties.color;const key=/celt|hallstatt|tène|galati|boii/i.test(f.properties.name)?'celtic':f.properties.sovereign||f.properties.group||f.properties.name;let hash=0;for(const c of key)hash=(hash*31+c.charCodeAt(0))>>>0;const palette=['#78b6a0','#d3ac76','#8bacc5','#c9b974','#ad93bd','#76b9b8','#c48c79','#9cb77c','#bf9ba1','#93a8ca','#c6a05e','#7ea897'];return palette[hash%palette.length];}
export function cultureForArea(f,cultures,year){const n=f.properties.name.toLowerCase();const rules=[[/^egypt$/,'egypt-old'],[/byzantine/ ,year<1204?'byz-early':'byz-late'],[/novgorod/,'novgorod'],[/^roman empire$/,'rome'],[/indus/,'indus'],[/norte chico/,'caral'],[/ming/,'ming'],[/mongol empire/,'mongol'],[/ottoman/,'ottoman'],[/sasan/,'sasan'],[/achaemen/,'persia'],[/western han/,'han-west'],[/eastern han/,'han-east'],[/^celts$|^celtic cultural/,'celts']];for(const [rx,id] of rules)if(rx.test(n)&&cultures.some(c=>c.id===id&&c.start<=year&&c.end>=year))return id;return null;}
export function religionFeatures(collection,year,filter='all'){const available=collection.snapshots.filter(s=>s<=year);if(!available.length)return {year:null,features:[]};const y=available.at(-1);return {year:y,features:collection.features.filter(f=>f.properties.snapshot===y&&year<=(f.properties.validUntil??y)&&(filter==='all'||f.properties.religion===filter))};}
export class TerritoryStore {
 // Native Window.fetch requires its global receiver in mobile browsers.
 // Keep the default call on globalThis rather than storing it as a store method.
 constructor(manifest,editorial,fetcher=(url)=>globalThis.fetch(url)){this.manifest=manifest;this.editorial=editorial;this.fetcher=fetcher;this.cache=new Map();this.pending=new Map();}
 async load(year){const snapshot=snapshotFor(this.manifest.snapshots,year);if(!snapshot)return null;let data=this.cache.get(snapshot.year);if(!data){let pending=this.pending.get(snapshot.year);if(!pending){pending=this.fetcher(`data/territories/${snapshot.file}`).then(r=>{if(!r.ok)throw Error('Не удалось загрузить территориальный срез');return r.json();}).then(d=>{this.cache.set(snapshot.year,d);if(this.cache.size>6)this.cache.delete(this.cache.keys().next().value);return d;}).finally(()=>this.pending.delete(snapshot.year));this.pending.set(snapshot.year,pending);}data=await pending;}return data;}
 cultureFeatures(data,year){const additions=this.editorial.features.filter(f=>f.properties.mode==='cultures'&&f.properties.start<=year&&year<=f.properties.end);return [...(data?.features||[]).filter(f=>!(/la t[eè]ne/i.test(f.properties.name)&&data.year<-450)),...additions];}
}
